<script setup lang="ts">
import {computed} from 'vue'
import {useTableWidths} from './tableWidths'
const props=defineProps<{orders:any[],loading:boolean,statuses:Record<string,string>,names:Record<string,string>}>()
const emit=defineEmits<{detail:[order:any],calculate:[order:any],sync:[]}>(),widths=useTableWidths('OrderRows')
const rows=computed(()=>props.orders.flatMap(order=>{const items=order.items.length?order.items:[null];return items.map((item:any,index:number)=>({order,item,index,count:items.length,key:order.id+':'+index}))}))
function span({row,column}:any){if(['image','product'].includes(column.columnKey))return [1,1];return row.index===0?[row.count,1]:[0,0]}
const money=(a:any,c:any)=>a==null?'—':new Intl.NumberFormat('zh-CN',{style:'currency',currency:c||'EUR'}).format(Number(a))
function unitPrice(item:any){const amount=item.display_amount??item.amount,quantity=Number(item.quantity);return amount!=null&&quantity>0&&Number.isFinite(quantity)&&Number.isFinite(Number(amount))?Number(amount)/quantity:null}
const date=(v:string)=>new Date(v).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'})
const time=(v:string)=>new Date(v).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false,hour:'2-digit',minute:'2-digit'})
function relative(v:string){const minutes=Math.max(0,Math.floor((Date.now()-new Date(v).getTime())/60000));return minutes<1?'片刻之前':minutes<60?minutes+' 分钟前':minutes<1440?Math.floor(minutes/60)+' 小时前':Math.floor(minutes/1440)+' 天前'}
</script>
<template>
<template v-if="true"><el-table :data="rows" :span-method="span" row-key="key" v-loading="loading" border class="amazon-orders" data-width-key="OrderRows/orders" @header-dragend="(w:number,_:number,c:any)=>widths.resize('orders',w,c)" @header-contextmenu="(c:any,e:MouseEvent)=>widths.resetColumn('orders',c,e)" @row-dblclick="(row:any)=>emit('detail',row.order)">
 <el-table-column column-key="date" label="订单日期" :width="widths.width('orders','date',140)"><template #default="{row}"><b>{{relative(row.order.purchased_at)}}</b><div class="order-muted">{{date(row.order.purchased_at)}}</div><div class="order-muted">{{time(row.order.purchased_at)}} 北京时间</div></template></el-table-column>
 <el-table-column column-key="details" label="订单详情" :width="widths.width('orders','details',245)"><template #default="{row}"><button class="order-link" @click="emit('detail',row.order)">{{row.order.order_id}}</button><div class="order-muted">店铺：{{row.order.store}}</div><div class="order-muted">站点：{{names[row.order.marketplace]||row.order.marketplace}} · {{row.order.marketplace}}</div><div class="order-muted">配送渠道：{{row.order.fulfilled_by==='AMAZON'?'亚马逊 FBA':row.order.fulfilled_by==='MERCHANT'?'自配送':'待返回'}}</div><div class="order-total">订单金额：<b>{{money(row.order.estimate?.display_amount??row.order.amount,row.order.estimate?.display_currency??row.order.currency)}}</b><small v-if="row.order.estimate?.amount_estimated"> · 售价预估</small></div></template></el-table-column>
 <el-table-column column-key="image" class-name="order-image-cell" label="图片" :width="widths.width('orders','image',94)"><template #default="{row}"><el-image v-if="row.item?.image_url" :src="row.item.image_url" fit="contain" class="order-image" loading="lazy"><template #error><span class="order-no-image">暂无图片</span></template></el-image><span v-else class="order-no-image">暂无图片</span></template></el-table-column>
 <el-table-column column-key="product" label="商品名称" :width="widths.width('orders','product')" min-width="360"><template #default="{row}"><template v-if="row.item"><button class="order-product-title" @click="emit('detail',row.order)">{{row.item.title||'商品信息待更新'}}</button><div class="order-muted">ASIN：<b>{{row.item.asin||'—'}}</b></div><div class="order-muted">SKU：{{row.item.sku||'—'}}</div><div class="order-muted">数量：<b>{{row.item.quantity}}</b></div><div class="order-muted">单价：{{money(unitPrice(row.item),row.item.display_currency??row.item.currency)}}</div></template><span v-else>商品信息待更新</span></template></el-table-column>
 <el-table-column column-key="profit" label="预估毛利" :width="widths.width('orders','profit',190)"><template #default="{row}"><el-tooltip :content="row.order.estimate?.method||'费用数据待获取'" placement="top"><b :class="{'negative-profit':Number(row.order.estimate?.gross_profit)<0}">{{money(row.order.estimate?.gross_profit,row.order.estimate?.display_currency??row.order.currency)}}</b></el-tooltip><el-button link type="primary" class="calculate-order" @click.stop="emit('calculate',row.order)">计算</el-button><div v-if="row.order.estimate?.gross_margin!=null" class="order-muted">毛利率 {{row.order.estimate.gross_margin}}%</div><div v-if="row.order.estimate?.fee_updated_at" class="order-muted">费用更新：{{new Date(row.order.estimate.fee_updated_at).toLocaleString('zh-CN')}}</div><div v-for="note in row.order.estimate?.notes" :key="note" class="order-muted">{{note}}</div></template></el-table-column>
 <el-table-column column-key="status" label="订单状态" :width="widths.width('orders','status',118)"><template #default="{row}"><span class="status-tag" :class="row.order.status"><i></i>{{statuses[row.order.status]||row.order.status}}</span></template></el-table-column>
 <el-table-column column-key="action" label="操作" :width="widths.width('orders','action',80)"><template #default="{row}"><el-button link type="primary" @click="emit('detail',row.order)">详情</el-button></template></el-table-column>
 <template #empty><el-empty description="暂无匹配的订单"></el-empty></template>
</el-table></template>
</template>
<style scoped>
.amazon-orders{border:0!important;--el-table-border-color:#e5ebe7;--el-table-header-bg-color:#f6f8f7;--el-table-row-hover-bg-color:#fafcfb}
.amazon-orders :deep(td.el-table__cell){vertical-align:top;padding:16px 0!important;border-right:0}
.amazon-orders :deep(th.el-table__cell){padding:12px 0!important;border-right:0;color:#44564e}
.amazon-orders :deep(.el-table__inner-wrapper:before),.amazon-orders :deep(.el-table__inner-wrapper:after),.amazon-orders:before,.amazon-orders:after{display:none!important}
.amazon-orders :deep(.el-table__border-left-patch){display:none}.amazon-orders :deep(.cell){word-break:normal;overflow-wrap:anywhere;line-height:1.65!important}
.order-link,.order-product-title{color:#247460;background:none;border:0;padding:0;text-align:left;line-height:1.65;font-size:13px}.order-link{font-weight:650;white-space:nowrap}.order-product-title{display:block;margin-bottom:5px;font-size:14px}.order-muted{color:#79877f;margin-top:4px}.order-muted small,.order-total small{display:block;font-size:11px}.order-total{margin-top:10px;color:#53695c}.order-image{width:68px;height:76px;display:block}.amazon-orders :deep(.order-image-cell .cell){padding-left:12px;padding-right:12px}.order-no-image{width:68px;min-height:64px;display:grid;place-items:center;font-size:11px;color:#9aa79f;background:#f5f7f6}.negative-profit{color:#e35151}.calculate-order{margin-left:10px}
</style>
